@app.get('/api/downloads/redeem')
async def redeem_download_ticket(
    ticket: str = Query(...),
    redis: aioredis.Redis = Depends(get_redis),
    current_user: User = Depends(get_current_user)
):
    ticket_payload = await redis.get(f"dl_ticket:{ticket}")
    if not ticket_payload:
        raise HTTPException(status_code=404, detail="Invalid or expired download ticket")

    data = json.loads(ticket_payload)
    if data.get("issued_to_user_id") != current_user.id:
        raise HTTPException(status_code=403, detail="Ticket was issued to a different user")

    return FileResponse(path=data["file_path"], filename=data["filename"])
